with deduped as (select * from sessions qualify row_number() over (partition by customer_id order by started_at desc, id) = 1) select date_trunc('quarter', started_at) as quarter_start, date_trunc('year', started_at) as year_start, sort_array(collect_set(browser)) as browser_list, (unix_timestamp(max(started_at)) - unix_timestamp(min(started_at))) / 60 as duration_min, count(case when device = 'tablet' then 1 end) as tablet_count, size(collect_set(device)) as num_devices from deduped group by grouping sets ((date_trunc('quarter', started_at), date_trunc('year', started_at)), (date_trunc('quarter', started_at)), ())
